import subprocess
import pandas as pd
import matplotlib.pyplot as plt

def task_func(script_path, output_file_path):
    try:
        result = subprocess.run(['python', script_path], check=True, capture_output=True, text=True)
    except subprocess.CalledProcessError as e:
        raise ValueError(f"Script execution failed: {e.stderr}") from e

    try:
        df = pd.read_csv(output_file_path)
    except Exception as e:
        raise ValueError(f"Failed to read CSV: {e}") from e

    if df.shape[1] != 2:
        raise ValueError("CSV must contain exactly two columns")

    ax = df.plot.bar(x=df.columns[0], y=df.columns[1], legend=False)
    plt.xlabel(df.columns[0])
    plt.ylabel(df.columns[1])
    return df, ax
